  const sync = async show => { try { await api(`/grades/sync${show ? "?show=true" : ""}`, { method: "POST" }); toast("Notenspiegel wird abgerufen…"); window.pollBg?.(); } catch (e) { toast(e.message, 4000); } };
  $("#qisSync").onclick = () => sync(false);
